<!-- 模块职责：展示结构化任务事实与当前进度；历史文本只作兼容，不反推业务字段。 -->
<script setup>
import { computed } from 'vue'
import Icon from '../components/Icon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { dateTime, eventNames, stageNames } from '../format'
const props = defineProps({ store: Object })
const store = props.store, s = store.state
const examples = [
  { icon: 'search', title: '查询订单', text: '查询订单 BF2026001 的状态，并说明是否超期未发货。', tag: '了解订单情况' },
  { icon: 'book', title: '了解政策', text: '超过承诺发货时间尚未发货，可以提出哪些处理建议？请给出政策来源。', tag: '获取政策依据' },
  { icon: 'shield', title: '申请处理', text: '查询订单 BF2026001，如果超期未发货，请根据政策生成待审核工单建议。', tag: '提交给负责人审核' },
]
const visibleTasks = computed(() => s.tab === 'workbench' ? s.tasks.slice(0, 5) : s.tasks)
</script>
<template>
  <div class="workspace-grid" :class="{ 'no-task': !s.task }">
    <div class="workspace-main">
      <section v-if="s.tab === 'workbench'" class="card composer-card">
        <div class="section-title"><span class="section-icon"><Icon name="spark" /></span><div><h2>你需要处理什么业务？</h2><p>查询信息、了解政策，或提交一份处理申请。</p></div></div>
        <form @submit.prevent="store.submitTask"><label class="sr-only" for="task-prompt">业务需求</label><div class="prompt-box"><textarea id="task-prompt" v-model="s.question" :disabled="s.busy" maxlength="2000" rows="4" placeholder="例如：帮我查询订单 BF2026001，如果超期未发货，请提交处理建议供负责人审核。" @keydown.ctrl.enter.prevent="store.submitTask"></textarea><div class="prompt-bottom"><span>涉及写入的操作会先提交负责人审核</span><span>{{ s.question.length }} / 2000</span></div></div><div class="composer-actions"><span>Ctrl + Enter 提交</span><button class="button primary" type="submit" :disabled="s.busy || !s.question.trim()">提交需求 <Icon name="arrow" :size="17" /></button></div></form>
      </section>
      <div v-if="s.tab === 'workbench' && !s.task" class="example-grid"><button v-for="item in examples" :key="item.title" class="example-card" :disabled="s.busy" @click="s.question = item.text"><Icon :name="item.icon" :size="20" /><strong>{{ item.title }}</strong><small>{{ item.tag }}</small><Icon name="arrow" :size="15" class="example-arrow" /></button></div>

      <section v-if="s.task" class="card result-card" data-task-detail><div class="card-header"><h2>处理结果</h2><StatusBadge :status="s.task.status" /></div><div class="result-body"><div class="request-quote">{{ s.task.user_input }}</div><section v-if="s.task.result?.query_result" class="prose-box" data-structured-result><h3>订单查询结果</h3><dl class="detail-list"><dt>订单编号</dt><dd>{{ s.task.result.query_result.order_id }}</dd><dt>订单状态</dt><dd>{{ s.task.result.query_result.status }}</dd><dt>创建时间</dt><dd>{{ dateTime(s.task.result.query_result.created_at) }}</dd><dt>承诺发货时间</dt><dd>{{ dateTime(s.task.result.query_result.promised_ship_at) }}</dd><dt>实际发货时间</dt><dd>{{ s.task.result.query_result.shipped_at ? dateTime(s.task.result.query_result.shipped_at) : '尚未发货' }}</dd><dt>查询时刻</dt><dd>{{ dateTime(s.task.result.assessment.checked_at) }}</dd><dt>超期未发货</dt><dd>{{ s.task.result.assessment.is_overdue_unshipped ? '是' : '否' }}</dd></dl><h3>处理建议</h3><p>{{ s.task.result.proposal?.description || '本次未生成待审核建议。' }}</p><h3 v-if="s.task.result.policy_sources.length">政策依据</h3><p v-for="source in s.task.result.policy_sources" :key="source.chunk_id">{{ source.document_title }} · {{ source.section }} · {{ source.source }}</p><h3>当前进度</h3><p>{{ s.task.status === 'waiting_approval' ? '等待负责人审核，尚未创建正式工单。' : s.task.status === 'executing' ? '已批准，等待执行。' : s.task.status === 'completed' && s.task.ticket_id ? '正式工单已创建。' : s.task.status === 'rejected' ? '建议已拒绝。' : s.task.error || '本次处理已结束。' }}</p></section><p v-else-if="s.task.answer" class="answer-text">{{ s.task.answer }}</p><p v-else-if="s.task.status === 'waiting_approval'" class="answer-text">建议已提交，正在等待负责人审核。进度会自动更新。</p><div v-else-if="s.task.error" class="inline-error">{{ s.task.error }}</div><p v-else class="muted">{{ s.task.status === 'running' ? '需求正在处理中，稍后可以刷新进度。' : '需求已保存，可以继续处理。' }}</p><div v-if="s.task.ticket_id" class="ticket-result-label">正式工单 <span class="mono selectable">{{ s.task.ticket_id }}</span></div><div class="button-row"><button v-if="s.task.status === 'created'" class="button primary small" :disabled="s.busy" @click="store.runTask">继续处理</button><button class="button secondary small" :disabled="s.busy" @click="store.taskOperation('refresh')"><Icon name="refresh" :size="14" />刷新进度</button><span class="last-updated">更新于 {{ dateTime(s.task.updated_at) }}</span></div><details class="task-technical"><summary>编号与更多操作</summary><dl class="detail-list"><dt>任务编号</dt><dd class="mono selectable">{{ s.task.task_id }} <button class="inline-copy" aria-label="复制任务编号" @click="store.copy(s.task.task_id)"><Icon name="copy" :size="13" /></button></dd><template v-if="s.task.approval_id"><dt>审核编号</dt><dd class="mono selectable">{{ s.task.approval_id }}</dd></template><dt>创建时间</dt><dd>{{ dateTime(s.task.created_at) }}</dd></dl><button class="text-button" :disabled="s.busy" @click="store.loadTask(s.task.task_id)">重新读取保存的结果</button><button v-if="s.task.status === 'running'" class="text-button recovery-link" :disabled="s.busy" @click="store.confirm('核对中断任务？', '系统会核对审核检查点。没有检查点的遗留执行会安全结束，不会重放写入。', '确认核对', () => store.taskOperation('recover'))">核对中断任务</button></details></div></section>

      <section class="card"><div class="card-header"><div><h2>{{ s.tab === 'history' ? '我的任务' : '最近处理' }}</h2><p>{{ s.tab === 'history' ? `共 ${s.taskTotal} 条本人任务，按提交时间排列` : '自己的处理记录，随时可以回来查看' }}</p></div><button class="text-button" :disabled="s.busy" @click="store.refreshHistory"><Icon name="refresh" :size="15" />更新</button></div>
        <div v-if="!s.tasks.length" class="empty-state"><span class="empty-icon"><Icon name="flow" :size="28" /></span><h3>还没有提交过需求</h3><p>提交后，处理结果会自动保存在这里。<br />重新登录也可以继续查看。</p></div>
        <div v-else class="task-list"><button v-for="task in visibleTasks" :key="task.task_id" class="task-row" :class="{ selected: s.task?.task_id === task.task_id }" :disabled="s.busy" @click="store.loadTask(task.task_id)"><span class="task-row-icon"><Icon :name="task.approval_id ? 'shield' : 'file'" :size="19" /></span><span class="task-row-text"><strong>{{ task.user_input }}</strong><small>{{ dateTime(task.created_at) }}</small></span><StatusBadge :status="task.status" /><Icon name="chevron" :size="16" /></button></div>
        <div v-if="s.tab === 'history' && s.taskTotal > s.taskLimit" class="inbox-pagination"><span>第 {{ Math.floor(s.taskOffset / s.taskLimit) + 1 }} 页</span><div><button class="button secondary small" :disabled="s.busy || s.taskOffset === 0" @click="store.taskPage(-1)">上一页</button><button class="button secondary small" :disabled="s.busy || s.taskOffset + s.taskLimit >= s.taskTotal" @click="store.taskPage(1)">下一页</button></div></div>
        <div v-if="s.tab === 'workbench' && s.tasks.length" class="task-list-footer"><button class="text-button" :disabled="s.busy" @click="store.navigate('history')">查看全部任务 <Icon name="arrow" :size="14" /></button></div>
        <details v-if="s.tab === 'history'" class="find-task"><summary>按编号找回任务</summary><form class="inline-form" @submit.prevent="store.loadTask()"><input v-model="s.taskInput" aria-label="任务编号" :disabled="s.busy" placeholder="输入已有任务编号" /><button class="button secondary small" :disabled="s.busy || !s.taskInput.trim()">查找</button></form></details>
      </section>
    </div>
    <aside v-if="s.task" class="workspace-aside"><section class="card timeline-card"><div class="card-header"><div><h2>处理过程</h2><p>已保存的流程记录</p></div><Icon name="clock" :size="18" /></div><div v-if="!s.events.length" class="small-empty">暂无处理记录。</div><ol v-else class="timeline"><li v-for="event in s.events" :key="event.event_id" :class="{ 'event-failed': event.status === 'failed' }"><span class="timeline-dot"></span><div><strong>{{ stageNames[event.step_name] || eventNames[event.event_type] || event.event_type }}</strong><time class="event-time">{{ dateTime(event.created_at) }}</time><details class="trace-details"><summary>记录说明</summary><p>{{ event.message }}</p></details></div></li></ol><button v-if="s.moreEvents" class="text-button load-more" :disabled="s.busy" @click="store.loadMoreEvents">更多记录</button></section></aside>
  </div>
</template>
